-- HLD (system design) mock interviews: problems get a track (lld | hld) + seeded HLD problems.
ALTER TABLE problems ADD COLUMN track TEXT NOT NULL DEFAULT 'lld';

INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('url-shortener', 'URL Shortener (TinyURL)', 'Easy', 'Turn long links into short ones and redirect billions of clicks fast.', 'Design a URL shortening service like TinyURL or bit.ly.

Users paste a long URL and get a short link. Anyone opening the short link is redirected to the original URL. The service is very read-heavy. Clarify the scale and features with the interviewer before designing.', '{"requirements": ["Shorten a URL and redirect from the short code", "Custom aliases and link expiry (in or out of scope)", "Analytics/click counts (in or out of scope)", "Read:write ratio is very high (e.g. 100:1)", "Non-functional: low-latency redirects, high availability, short codes not guessable/sequential if required"], "estimation": ["New URLs per day/month and resulting write QPS", "Redirect QPS (average and peak) from the read:write ratio", "Storage over 5-10 years (bytes per record x records)", "Short code length derived from keyspace (base62, 7 chars ~ 3.5 trillion)", "Cache size for hot URLs (e.g. 20% of daily reads)"], "api": ["POST /urls {longUrl, alias?, expiry?} -> shortUrl", "GET /{code} -> 301/302 redirect with reason for the choice", "Table: code (PK), long_url, created_at, expiry, user_id", "Database choice justified (key-value/NoSQL for simple lookups at scale, or SQL with reasoning)"], "architecture": ["Client -> load balancer -> stateless app servers", "Cache (Redis) in front of the DB for redirects", "Code generation component (counter + base62, key generation service, or hashing with collision check)", "Database for mappings; optional analytics via async queue", "Walkthrough of both the create and the redirect flow"], "deepdive": ["Unique code generation without collisions across servers (KGS / ranges per server / Snowflake-like IDs)", "Cache strategy and eviction (LRU), cache hit ratio", "Sharding by code/hash; replication for read scale", "Handling hot links and expiry cleanup", "Availability over consistency for redirects (CAP choice explained)"], "twist": ["Add per-link click analytics without slowing down redirects", "A link goes viral and gets 1M hits per minute", "Users want custom aliases, which can collide", "Make short links unguessable for private documents"]}', 1, 0, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('chat-app', 'Chat App (WhatsApp)', 'Medium', '1:1 and group messaging with delivery status, online presence and offline delivery.', 'Design a chat application like WhatsApp.

Users send messages to each other one-to-one and in groups. Messages should arrive in real time when the receiver is online and be delivered later when they come back online. Agree on the scope with the interviewer first.', '{"requirements": ["1:1 and group messaging; group size limit", "Sent / delivered / read receipts", "Online/last-seen presence", "Offline delivery and message history", "Media (in or out of scope); end-to-end encryption mentioned", "Non-functional: low latency, messages never lost, ordering within a chat"], "estimation": ["DAU and messages per user per day -> messages/sec (avg, peak)", "Concurrent connections to hold open", "Storage per day/year for message text (and media separately)", "Bandwidth estimate"], "api": ["Persistent connection (WebSocket) with message events instead of only REST", "send_message(chat_id, client_msg_id, content), ack events", "Message table keyed by (chat_id, message_id/time) for ordered reads", "Wide-column/NoSQL (e.g. Cassandra) justified for write-heavy time-ordered data", "Group membership and user/device tables"], "architecture": ["Clients connected to chat/gateway servers over WebSockets via load balancer", "Session/presence service mapping user -> connection server (Redis)", "Message service persisting to DB, routing to receiver''s server", "Queue for offline users + push notification service", "Media via object storage + CDN", "Walkthrough of a message from sender to an online and an offline receiver"], "deepdive": ["Routing messages between gateway servers (pub/sub or lookup)", "Ordering and idempotency (client message id, sequence per chat)", "Group fan-out strategy for large groups", "Presence at scale (heartbeats, TTLs)", "Partitioning messages by chat_id; replication; durability before ack"], "twist": ["Support the same account on phone and laptop at once", "Groups grow to 50,000 members (channels)", "A gateway server crashes with 1M users connected", "Add message search"]}', 1, 1, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('news-feed', 'News Feed (Instagram / Twitter)', 'Medium', 'Post, follow and see a ranked home feed of people you follow.', 'Design the home news feed for a social app like Instagram or Twitter.

Users post content and follow other users. When they open the app they see a feed of recent posts from people they follow. Some users have millions of followers. Clarify scope before you design.', '{"requirements": ["Create posts; follow/unfollow; view home feed", "Chronological vs ranked feed decided", "Pagination/infinite scroll", "Media handling (in or out of scope)", "Non-functional: feed loads fast (<200ms), eventual consistency acceptable, highly available"], "estimation": ["DAU, posts/day -> write QPS", "Feed reads/day -> read QPS (much higher than writes)", "Average followers and the celebrity outlier", "Storage for posts and feed caches"], "api": ["POST /posts, POST /follow/{id}, GET /feed?cursor=", "Cursor-based pagination explained", "Tables: users, follows(follower, followee), posts(author, created_at)", "Store choice for follow graph and feed cache justified"], "architecture": ["Post service, follow/graph service, feed service", "Fan-out workers via a message queue", "Feed cache per user (Redis lists)", "Object storage + CDN for media", "Walkthrough of posting and of reading the feed"], "deepdive": ["Fan-out on write vs fan-out on read and the hybrid for celebrities", "Feed cache size limits and backfill for inactive users", "Ranking signals (if ranked) and where ranking runs", "Sharding posts by user_id; hot-key handling", "Consistency trade-offs (eventual is fine) and failure of fan-out workers"], "twist": ["A celebrity with 50M followers posts", "Switch from chronological to a ranked feed", "Users want to see posts from accounts they don''t follow (recommendations)", "Deleting a post must remove it from all feeds quickly"]}', 1, 2, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('notification-system', 'Notification System', 'Medium', 'Send push, SMS and email notifications reliably at scale.', 'Design a notification service that other teams use to send push notifications, SMS and emails to users.

Examples: order shipped, OTPs, marketing campaigns to millions of users. Clarify which channels, priorities and guarantees matter.', '{"requirements": ["Channels: push, SMS, email; per-user preferences and opt-outs", "Transactional (OTP) vs promotional priorities", "Scheduled and bulk/campaign sends", "Templates and localisation", "Non-functional: at-least-once delivery, no duplicates to users, OTP latency in seconds, rate limits"], "estimation": ["Notifications per day per channel -> QPS, peak during campaigns", "Burst size of a campaign (e.g. 10M in an hour)", "Storage for notification logs/status"], "api": ["POST /notifications {user_id(s), template_id, params, channels, priority, idempotency_key}", "Status tracking endpoint or callbacks", "Tables: notifications(status), user_preferences, templates, device tokens", "Idempotency key handling"], "architecture": ["Notification API -> validation + preference check", "Priority queues per channel (Kafka/SQS)", "Channel workers calling third-party providers (FCM/APNs, SMS gateway, email provider)", "Retry with backoff + dead-letter queue", "Scheduler for delayed sends; status/analytics store", "Walkthrough of an OTP and of a campaign"], "deepdive": ["Separate queues so campaigns never delay OTPs", "Deduplication and idempotency across retries", "Provider failover and rate limiting per provider", "Scaling workers horizontally; partitioning", "Tracking delivery status via provider callbacks"], "twist": ["The SMS provider goes down during a big sale", "Respect quiet hours in each user''s timezone", "Marketing wants to send 50M notifications in 10 minutes", "A bug sent the same notification 3 times: prevent it"]}', 1, 3, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('video-streaming', 'Video Streaming (YouTube)', 'Hard', 'Upload, process and stream videos to millions of viewers worldwide.', 'Design a video platform like YouTube.

Creators upload videos; viewers watch them on any device and network speed. Popular videos get massive traffic. Agree with the interviewer which parts to focus on.', '{"requirements": ["Upload videos; watch/stream; search and recommendations in or out of scope", "Multiple resolutions and adaptive bitrate", "View counts, likes, comments (scope decided)", "Non-functional: smooth playback worldwide, uploads durable, highly available reads"], "estimation": ["Uploads/day and average size -> ingest bandwidth and storage (including multiple renditions)", "Views/day -> egress bandwidth (dominant cost)", "Read:write ratio", "Storage growth per year"], "api": ["Resumable/chunked upload API (initiate, upload parts, complete)", "GET /videos/{id} metadata and manifest (HLS/DASH)", "Tables: videos(metadata, status), users, view counts", "Blob storage for video files vs DB for metadata"], "architecture": ["Upload service -> object storage (raw)", "Queue -> transcoding workers producing renditions + manifests", "CDN serving segments close to users", "Metadata service + DB + cache", "Walkthrough of upload-to-playable and of a playback request"], "deepdive": ["Transcoding pipeline as a DAG, parallel chunks, retries", "Adaptive bitrate streaming (segments, manifests)", "CDN strategy: popular vs long-tail content, origin shielding", "View counting at scale (approximate, batched/async)", "Cost/latency trade-offs and failure handling"], "twist": ["Add live streaming", "A video goes viral in one country", "Cut storage costs by 40%", "Creators complain uploads fail on slow mobile networks"]}', 1, 4, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('ride-hailing', 'Ride Hailing (Uber / Ola)', 'Hard', 'Match riders with nearby drivers in real time, with live location tracking.', 'Design a ride-hailing service like Uber or Ola.

Riders request a ride; nearby drivers get the request and one accepts. Both see each other''s live location until the trip ends. Clarify scope (pricing, payments, pooling) first.', '{"requirements": ["Request ride, match to nearby driver, accept/reject, trip lifecycle", "Live driver location updates and ETA", "Fare estimate and surge (in or out of scope)", "Payments, ratings (scope decided)", "Non-functional: matching within seconds, high write rate of locations, consistency for driver assignment"], "estimation": ["Active drivers and location update interval -> location writes/sec", "Ride requests/sec at peak", "Storage for trips; location history retention"], "api": ["Driver location update (frequent, lightweight; WebSocket/UDP-ish)", "POST /rides request, driver accept, trip state transitions", "Tables: trips(state), drivers(status), riders", "Geospatial index choice (geohash/quadtree/H3, Redis GEO) justified"], "architecture": ["Location service ingesting updates into an in-memory geo index", "Matching/dispatch service querying nearby available drivers", "Trip service with state machine and DB", "Notification/WebSocket gateway to riders and drivers", "Pricing/ETA service; payments via queue", "Walkthrough from ride request to driver assigned"], "deepdive": ["Geo partitioning (cells/geohash) and hot areas like airports", "Preventing double assignment of a driver (locks/atomic state change)", "Handling driver timeouts and re-matching", "Scaling location writes (in-memory, sharded by region)", "Consistency vs availability choices per component"], "twist": ["Add shared rides (pooling) with multiple riders", "Rush hour at a stadium: 20,000 requests in 10 minutes", "A driver''s phone loses network mid-trip", "Expand to a new country with different pricing rules"]}', 1, 5, 'hld', strftime('%s','now'));
